            self.sift_down(nums, index, n)

        for end in range(n - 1, -1, -1):
            nums[0], nums[end] = nums[end], nums[0]
            self.sift_down(nums, 0, end)

        nums.reverse()

    def sift_down(self, nums, index, size):
        while True:
            smallest = index
            left = 2 * index + 1
            right = left + 1

